ul.li:
HiveCatalog. Omitting paimon.catalog, or setting it to hive, uses the Hive catalog. A managed table is created in the Hive Metastore warehouse:
CREATE TABLE paimon_hive_cat(userid INT, movieId INT) STORED AS PAIMON;
An external Hive-catalog table must set LOCATION. Do not set paimon.catalog_location or paimon.table_identifier on a Hive-catalog table. Any paimon.catalog value other than hadoop is treated as the Hive catalog. JDBC and REST catalogs are not supported.

li.codeblock:
CREATE TABLE support_partitioned_by_table2 (
user_id BIGINT COMMENT 'The user_id field',
item_id BIGINT COMMENT 'The item_id field',
behavior STRING COMMENT 'The behavior field'
)
PARTITIONED BY (
dt STRING COMMENT 'The dt field',
hh STRING COMMENT 'The hh field'
)
STORED AS PAIMON;

CREATE TABLE test_create_managed_part_pk_paimon_table (
user_id BIGINT COMMENT 'The user_id field',
item_id BIGINT COMMENT 'The item_id field',
behavior STRING COMMENT 'The behavior field'
)
PARTITIONED BY (
dt STRING COMMENT 'The dt field',
hh STRING COMMENT 'The hh field'
)
STORED AS PAIMON
TBLPROPERTIES (
'primary-key'='user_id'
);

CREATE TABLE test_create_managed_bucket_paimon_table (
user_id BIGINT COMMENT 'The user_id field',
item_id BIGINT COMMENT 'The item_id field',
behavior STRING COMMENT 'The behavior field'
)
STORED AS PAIMON
TBLPROPERTIES (
'bucket'='4',
'bucket-key'='behavior'
);

CREATE EXTERNAL TABLE ext_paimon_table
STORED AS PAIMON
LOCATION 'underlying_paimon_table_location';
